-- =============================================================================
-- CMSDatabase -- Vita Test Agent tables (Vita* + VitaAlembicVersion)
-- =============================================================================
-- Generated by `python -m vita.store.ddl` from the Vita store's Alembic revisions (vita/store/migrations);
-- do not edit by hand. Creates every table and index the Vita TestAgent store uses, so the Vita app login
-- needs only data read/write rights on them (db_datareader + db_datawriter, or GRANT SELECT, INSERT, UPDATE,
-- DELETE on the Vita* tables) and runs with VITA_AUTO_MIGRATE=0.
--
-- Idempotent and safe to re-run: each CREATE TABLE / CREATE INDEX is guarded by IF NOT EXISTS, and the
-- Alembic version row is inserted only when missing. It never alters or drops an existing table: later schema
-- changes ship as new Alembic revisions, applied with `vita db upgrade` (or a regenerated script).
--
-- Text columns are NVARCHAR, timestamps DATETIME2 holding UTC.
--
-- A CMSDatabase that already holds Vita tables created by an older Vita (the app's own create_all) must be
-- brought forward once with `vita db upgrade` instead (it adds columns, rebuilds the graph tables, merges
-- duplicate cases, then stamps the version); this script would skip those tables and fail on the new indexes.
-- =============================================================================

USE CMSDatabase;
GO

SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO

IF OBJECT_ID(N'dbo.VitaAlembicVersion', N'U') IS NULL
BEGIN
    CREATE TABLE [VitaAlembicVersion] (
        version_num VARCHAR(32) NOT NULL, 
        CONSTRAINT [VitaAlembicVersion_pkc] PRIMARY KEY (version_num)
    );
END;
GO

IF OBJECT_ID(N'dbo.VitaAlerts', N'U') IS NULL
BEGIN
    CREATE TABLE [VitaAlerts] (
        id INTEGER NOT NULL IDENTITY, 
        fingerprint VARCHAR(80) NULL, 
        sent_at DATETIME2 NULL, 
        subject NVARCHAR(400) NULL, 
        channels_json NVARCHAR(max) NULL, 
        PRIMARY KEY (id)
    );
END;
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'ix_VitaAlerts_fingerprint' AND object_id = OBJECT_ID(N'dbo.VitaAlerts'))
BEGIN
    CREATE INDEX [ix_VitaAlerts_fingerprint] ON [VitaAlerts] (fingerprint);
END;
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'ix_VitaAlerts_sent_at' AND object_id = OBJECT_ID(N'dbo.VitaAlerts'))
